async function loadSettings(){const response=await fetch('/api/admin/settings',{cache:'no-store'});if(!response.ok)return;const settings=await response.json();activeTrackRevision=settings.trackRevision??null;$('#sessionName').value=settings.sessionName;$('#raceLaps').value=settings.totalRaceLaps;$('#minimumRequiredPitStops').value=settings.minimumRequiredPitStops??1;$('#sectorCount').value=settings.sectorCount;$('#automaticYellow').checked=settings.automaticYellowEnabled;$('#automaticCollisionInvestigations').checked=settings.automaticCollisionInvestigationsEnabled===true;$('#disconnectedLapRecovery').checked=settings.disconnectedLapRecoveryEnabled===true;$('#allowTeams').checked=settings.allowTeams!==false;$('#trackName').value=settings.trackName??'';$('#trackId').value=settings.trackId??'';$('#trackPackageHash').value=settings.trackPackageHash??'';$('#trackLimitMode').value=settings.trackLimitMode??'warningsOnly';$('#slowSpeedKph').value=settings.slowSpeedKph;$('#slowDurationSeconds').value=settings.slowDurationSeconds;$('#severeLateralOffsetMeters').value=settings.severeLateralOffsetMeters;$('#recoveryDurationSeconds').value=settings.recoveryDurationSeconds;$('#teamCount').value=settings.teamCount??settings.teams?.length??2;$('#driversPerTeam').value=settings.driversPerTeam??6;teamDraft=(settings.teams??[]).map(team=>({...team}));renderTeamRows(numberValue('#teamCount'));toggleTeamSettings();rebuildSectorOptions(settings.sectorCount);}
