async function saveCollisionInvestigationToggle(){const control=$('#automaticCollisionInvestigations');control.disabled=true;const response=await request('/api/admin/collision-investigations',{enabled:control.checked});control.disabled=false;if(!response.ok){actionError.textContent=(await safeJson(response))?.error??'碰撞调查开关保存失败';await loadSettings();return;}actionError.textContent=control.checked?'疑似碰撞自动调查已启用':'疑似碰撞自动调查已关闭，已有调查仍会保留';setTimeout(()=>{if(actionError.textContent.includes('碰撞自动调查'))actionError.textContent='';},2500);}
function toggleTeamSettings(){$('#teamSettings').classList.toggle('hidden',!$('#allowTeams').checked);}
function resizeTeamRows(){teamDraft=readTeamRows();renderTeamRows(numberValue('#teamCount'));}
function renderTeamRows(requested){const count=Math.min(12,Math.max(1,Math.round(requested)||1)),root=$('#teamRows');$('#teamCount').value=count;root.replaceChildren();for(let index=0;index<count;index++){const generated=!teamDraft[index],existing=teamDraft[index]??{id:`team-${index+1}`,name:`车队 ${index+1}`,themeColor:defaultTeamColors[index%defaultTeamColors.length]};const row=document.createElement('div');row.className='team-row';row.dataset.teamId=existing.id||`team-${index+1}`;const number=document.createElement('span');number.className='team-number';number.textContent=String(index+1);number.style.backgroundColor=existing.themeColor||defaultTeamColors[index%defaultTeamColors.length];const name=document.createElement('input');name.type='text';name.maxLength=24;name.value=generated?tr(existing.name??''):existing.name??'';name.placeholder=`车队 ${index+1} 名称`;name.setAttribute('aria-label',`第 ${index+1} 支车队名称`);const color=document.createElement('input');color.type='color';color.value=/^#[0-9a-f]{6}$/i.test(existing.themeColor??'')?existing.themeColor:defaultTeamColors[index%defaultTeamColors.length];color.setAttribute('aria-label',`第 ${index+1} 支车队代表色`);color.addEventListener('input',()=>number.style.backgroundColor=color.value);row.append(number,name,color);root.append(row);}}
