function sessionCommand(phase){const count=Math.min(3,Math.max(1,numberValue('#qualifyingSessionCount')||1)),practiceCount=Math.min(3,Math.max(1,numberValue('#practiceSessionCount')||1));return{phase,sessionName:null,totalRaceLaps:null,countdownSeconds:numberValue('#countdownSeconds'),qualifyingMinutes:numberValue('#qualifyingMinutes'),qualifyingSessionCount:count,qualifyingSessionMinutes:count===1?null:[numberValue('#qualifyingQ1Minutes'),numberValue('#qualifyingQ2Minutes'),numberValue('#qualifyingQ3Minutes')].slice(0,count),qualifyingEliminationCounts:count===1?null:[optionalNumber('#qualifyingQ1Eliminations'),optionalNumber('#qualifyingQ2Eliminations')].slice(0,count-1),practiceSessionCount:practiceCount,practiceSessionMinutes:[numberValue('#practiceFP1Minutes'),numberValue('#practiceFP2Minutes'),numberValue('#practiceFP3Minutes')].slice(0,practiceCount)};}
