  const displayed=Math.min(150,Math.max(70,distance*32)),centerX=280,centerY=90,leftX=centerX-ux*displayed/2,leftY=centerY-uz*displayed/2,rightX=centerX+ux*displayed/2,rightY=centerY+uz*displayed/2;
