async function uploadOrganizerLogo(){const status=$('#organizerLogoStatus'),file=$('#organizerLogoFile').files?.[0];if(!file){status.textContent='请先选择 PNG 或 JPEG 图片。';status.className='track-package-status error';return;}if(file.size>262144){status.textContent='图片超过 256 KiB 上限。';status.className='track-package-status error';return;}const form=new FormData();form.append('file',file);status.textContent='正在上传并校验…';status.className='track-package-status';const response=await fetch('/api/admin/organizer-logo',{method:'POST',body:form});if(!response.ok){status.textContent=(await safeJson(response))?.error??'Logo 上传失败。';status.className='track-package-status error';return;}await loadOrganizerLogoStatus();}
async function deleteOrganizerLogo(){const response=await fetch('/api/admin/organizer-logo',{method:'DELETE'});if(!response.ok){const status=$('#organizerLogoStatus');status.textContent=(await safeJson(response))?.error??'恢复默认 Logo 失败。';status.className='track-package-status error';return;}$('#organizerLogoFile').value='';await loadOrganizerLogoStatus();}
function exportResultsCsv(){const state=requireResultState();if(!state)return;const header=['排名','车手','车队','状态','完成圈数','最快圈','正赛总时间','与第一名差','计时罚时'].map(tr);const leaderLaps=state.participants[0]?.completedLaps??0;const rows=state.participants.map(item=>[item.position,item.displayName,item.teamName??'',tr(participantStatusText(item)),item.completedLaps,formatTime(item.bestLapSeconds),formatRaceTime(item.adjustedRaceTotalSeconds??item.raceTotalSeconds),participantComparison(item,leaderLaps),item.timePenaltySeconds??0]);const csv='\uFEFF'+[header,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),resultFileName(state,'csv'));}
function exportResultsPng(){const state=requireResultState();if(!state)return;const width=1600,rowHeight=70,height=Math.max(900,410+state.participants.length*rowHeight),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#080b11';ctx.fillRect(0,0,width,height);ctx.fillStyle='#38d5e8';ctx.fillRect(0,0,12,height);ctx.fillStyle='#38d5e8';ctx.font='600 22px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText('LAZYFORZA · ESTATE RACING',70,70);ctx.fillStyle='#f8fafc';ctx.font='700 52px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText(state.phase==='grid'?'排位赛完整成绩':'正赛完整成绩',70,140);ctx.fillStyle='#9aabba';ctx.font='24px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText(`${state.sessionName} · ${state.trackName??'地产环道'} · ${new Date().toLocaleString(raceLocale,{hour12:false})}`,70,185);const columns=[70,170,520,780,940,1120,1370],labels=['POS','DRIVER','TEAM','LAPS',state.phase==='grid'?'BEST LAP':'TOTAL','DELTA','PENALTY'];ctx.fillStyle='#111925';ctx.fillRect(50,235,1500,58);ctx.fillStyle='#8fa0b2';ctx.font='600 18px Segoe UI, Microsoft YaHei, sans-serif';labels.forEach((label,index)=>ctx.fillText(label,columns[index],271));const leaderLaps=state.participants[0]?.completedLaps??0;state.participants.forEach((item,index)=>{const y=293+index*rowHeight;ctx.fillStyle=index%2===0?'#0d141e':'#111925';ctx.fillRect(50,y,1500,rowHeight-2);ctx.fillStyle=item.themeColor||'#38d5e8';ctx.fillRect(50,y,7,rowHeight-2);ctx.fillStyle='#f8fafc';ctx.font='600 24px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText(String(item.position),columns[0],y+43);ctx.fillText(item.displayName,columns[1],y+43);ctx.font='21px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillStyle='#b8c4d0';ctx.fillText(item.teamName??'个人参赛',columns[2],y+43);ctx.fillText(String(item.completedLaps),columns[3],y+43);ctx.fillStyle='#f8fafc';ctx.fillText(state.phase==='grid'?formatTime(item.bestLapSeconds):formatRaceTime(item.adjustedRaceTotalSeconds??item.raceTotalSeconds),columns[4],y+43);ctx.fillText(participantComparison(item,leaderLaps),columns[5],y+43);ctx.fillStyle=(item.timePenaltySeconds??0)>0?'#ffcf4a':'#778697';ctx.fillText((item.timePenaltySeconds??0)>0?`+${item.timePenaltySeconds.toFixed(0)}s`:'—',columns[6],y+43);});ctx.fillStyle='#718096';ctx.font='18px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText('成绩来自参赛车手 LazyForza 上报；不是 FH6 官方比赛结果。',70,height-42);canvas.toBlob(blob=>{if(blob)downloadBlob(blob,resultFileName(state,'png'));},'image/png');}
function requireResultState(){if(!lastState||!['grid','finished'].includes(lastState.phase)){actionError.textContent='只有排位赛冻结后或正赛结束后才能导出成绩。';return null;}return lastState;}
function resultFileName(state,extension){const phase=tr(state.phase==='grid'?'排位赛':'正赛');return`LazyForza-${phase}-${raceI18n.isEnglish?'full-results':'完整成绩'}-${new Date().toISOString().replace(/[:T]/g,'-').slice(0,16)}.${extension}`;}
function exportStageResultCsv(result){const header=['排名','车手','车队','状态','完成圈数','最快圈','总时间','与第一名差','计时罚时'].map(tr),leader=result.participants[0],rows=result.participants.map(item=>[item.position,item.displayName,item.teamName??'',tr(stageResultStatus(result,item)),item.completedLaps,formatTime(item.bestLapSeconds),formatRaceTime(item.adjustedRaceTotalSeconds??item.raceTotalSeconds),stageResultComparison(item,leader),item.timePenaltySeconds??0]),csv='\uFEFF'+[header,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),stageResultFileName(result,'csv'));}
function exportStageResultPng(result){const width=1600,rowHeight=70,height=Math.max(900,410+result.participants.length*rowHeight),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#080b11';ctx.fillRect(0,0,width,height);ctx.fillStyle=result.phase==='race'?'#b8f34a':'#42d7e8';ctx.fillRect(0,0,12,height);ctx.fillStyle='#42d7e8';ctx.font='600 22px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText('LAZYFORZA · RESULT ARCHIVE',70,70);ctx.fillStyle='#f8fafc';ctx.font='700 52px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText(`${result.label} 阶段赛果`,70,140);ctx.fillStyle='#9aabba';ctx.font='24px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText(`${result.sessionName} · ${result.trackName??'地产环道'} · ${new Date(result.completedAt).toLocaleString(raceLocale,{hour12:false})}`,70,185);const columns=[70,170,520,780,940,1120,1370],labels=['POS','DRIVER','TEAM','LAPS',result.phase==='race'?'TOTAL':'BEST LAP','DELTA','PENALTY'];ctx.fillStyle='#111925';ctx.fillRect(50,235,1500,58);ctx.fillStyle='#8fa0b2';ctx.font='600 18px Segoe UI, Microsoft YaHei, sans-serif';labels.forEach((label,index)=>ctx.fillText(label,columns[index],271));const leader=result.participants[0];result.participants.forEach((item,index)=>{const y=293+index*rowHeight;ctx.fillStyle=index%2===0?'#0d141e':'#111925';ctx.fillRect(50,y,1500,rowHeight-2);ctx.fillStyle=item.themeColor||'#42d7e8';ctx.fillRect(50,y,7,rowHeight-2);ctx.fillStyle='#f8fafc';ctx.font='600 24px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText(String(item.position),columns[0],y+43);ctx.fillText(item.displayName,columns[1],y+43);ctx.font='21px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillStyle='#b8c4d0';ctx.fillText(item.teamName??'个人参赛',columns[2],y+43);ctx.fillText(String(item.completedLaps),columns[3],y+43);ctx.fillStyle='#f8fafc';ctx.fillText(result.phase==='race'?formatRaceTime(item.adjustedRaceTotalSeconds??item.raceTotalSeconds):formatTime(item.bestLapSeconds),columns[4],y+43);ctx.fillText(stageResultComparison(item,leader),columns[5],y+43);ctx.fillStyle=(item.timePenaltySeconds??0)>0?'#ffcf4a':'#778697';ctx.fillText((item.timePenaltySeconds??0)>0?`+${Number(item.timePenaltySeconds).toFixed(0)}s`:'—',columns[6],y+43);});ctx.fillStyle='#718096';ctx.font='18px Segoe UI, Microsoft YaHei, sans-serif';ctx.fillText('成绩来自参赛车手 LazyForza 上报；不是 FH6 官方比赛结果。',70,height-42);canvas.toBlob(blob=>{if(blob)downloadBlob(blob,stageResultFileName(result,'png'));},'image/png');}
function stageResultFileName(result,extension){const time=new Date(result.completedAt).toISOString().replace(/[:T]/g,'-').slice(0,16),label=tr(result.label);return `LazyForza-${label}-${raceI18n.isEnglish?'results':'阶段赛果'}-${time}.${extension}`;}
function csvCell(valueToWrite){const source=String(valueToWrite??'');return/[",\r\n]/.test(source)?`"${source.replaceAll('"','""')}"`:source;}
function downloadBlob(blob,fileName){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=fileName;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function post(url,body){actionError.textContent='';const response=await request(url,body);if(!response.ok){actionError.textContent=(await safeJson(response))?.error??`操作失败：HTTP ${response.status}`;return;}await refresh();await loadResultHistory();}
function request(url,body){return fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});}
async function responseError(response,fallback){const text=await response.text();try{const parsed=JSON.parse(text);if(parsed?.error)return parsed.error;}catch{}const runtimeCode=text.match(/(?:Error\s*)?(1101|1102|1027)\b/i)?.[1];if(runtimeCode==='1101')return'Cloudflare Worker 运行时发生异常。请重新部署最新服务端，并在 Workers 日志中查看失败请求。';if(runtimeCode==='1102')return'Cloudflare Worker 超出运行资源限制。请重新部署最新服务端；若仍出现，请在 Workers 日志中查看 CPU 与内存用量。';if(runtimeCode==='1027')return'Cloudflare 免费额度已经用完，请等待额度重置或更换账号套餐。';return`${fallback}（HTTP ${response.status}）`;}
function actionButton(label,handler){const button=document.createElement('button');button.type='button';button.textContent=label;button.addEventListener('click',handler);return button;}
function cell(content,className=''){const td=document.createElement('td');td.className=className;td.textContent=content??'—';return td;}
function formatTime(seconds){if(seconds===null||seconds===undefined||!Number.isFinite(seconds)||seconds<=0)return'—';const minutes=Math.floor(seconds/60);return`${minutes}:${(seconds%60).toFixed(3).padStart(6,'0')}`;}
function formatRaceTime(seconds){if(seconds===null||seconds===undefined||!Number.isFinite(seconds)||seconds<0)return'—';const milliseconds=Math.round(seconds*1000),hours=Math.floor(milliseconds/3600000),minutes=Math.floor(milliseconds%3600000/60000),wholeSeconds=Math.floor(milliseconds%60000/1000),fraction=milliseconds%1000;return hours>0?`${hours}:${String(minutes).padStart(2,'0')}:${String(wholeSeconds).padStart(2,'0')}.${String(fraction).padStart(3,'0')}`:`${minutes}:${String(wholeSeconds).padStart(2,'0')}.${String(fraction).padStart(3,'0')}`;}
function formatDelta(seconds){if(seconds===null||seconds===undefined||!Number.isFinite(seconds))return'—';if(Math.abs(seconds)<.0005)return'±0.000';return`${seconds>0?'+':''}${seconds.toFixed(3)}`;}
function participantComparison(participant,_leaderLaps){if(participant.position===1)return'LEADER';if(Number.isFinite(participant.gapToLeaderSeconds))return formatDelta(participant.gapToLeaderSeconds);const leader=lastState?.participants?.[0];if(!leader)return'—';const leaderDistance=(leader.completedLaps??0)+Math.max(0,Math.min(1,leader.trackProgress??0));const participantDistance=(participant.completedLaps??0)+Math.max(0,Math.min(1,participant.trackProgress??0));const lapGap=Math.floor(Math.max(0,leaderDistance-participantDistance)+1e-9);return lapGap>0?`+${lapGap} ${lapGap===1?'LAP':'LAPS'}`:'—';}
function text(selector,valueToSet){$(selector).textContent=valueToSet;}function value(selector){return $(selector).value.trim();}function numberValue(selector){return Number.parseFloat($(selector).value);}async function safeJson(response){try{return await response.json();}catch{return null;}}
